mapper.select:
select exists(
    select repository_id from app_source_repository_slots where repository_id = #{repositoryId}
    union all
    select repository_id from app_source_snapshots where repository_id = #{repositoryId}
    union all
    select repository_id from app_source_cleanup_tasks where repository_id = #{repositoryId}
    union all
    select repository_id from app_source_operations where repository_id = #{repositoryId}
)

mapper.update:
update app_source_repository_slots set active_generation = #{row.activeGeneration},
    pending_generation = #{row.pendingGeneration}, next_generation = #{row.nextGeneration},
    latest_operation_id = #{row.latestOperationId}, lock_version = #{row.lockVersion}, updated_at = #{row.updatedAt}
where repository_id = #{row.repositoryId} and lock_version = #{expectedLockVersion}

update app_source_replicas set status = 'RUNNING', lease_owner = #{leaseOwner}, lease_until = #{leaseUntil},
    attempt_count = attempt_count + 1, next_retry_at = null, safe_error_code = null,
    safe_error_message = null, updated_at = #{now}
where repository_id = #{repositoryId} and generation = #{generation} and linux_server_id = #{linuxServerId}
  and (status in ('PENDING', 'FAILED', 'STALE') or (status = 'RUNNING' and lease_until <= #{now}))

update app_source_replicas set runtime_workspace_id = #{row.runtimeWorkspaceId}, status = #{row.status},
    lease_owner = #{row.leaseOwner}, lease_until = #{row.leaseUntil}, attempt_count = #{row.attemptCount},
    next_retry_at = #{row.nextRetryAt}, safe_error_code = #{row.safeErrorCode},
    safe_error_message = #{row.safeErrorMessage}, updated_at = #{row.updatedAt}
where repository_id = #{row.repositoryId} and generation = #{row.generation}
  and linux_server_id = #{row.linuxServerId} and status = 'RUNNING'
  and lease_owner = #{expectedLeaseOwner} and lease_until > #{now}

mapper.select:
select repository_id from app_source_replicas
where repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'RUNNING'
  and lease_owner = #{expectedLeaseOwner} and lease_until > #{now}
for update

mapper.update:
update app_source_replicas set status = 'CLEANED', lease_owner = null, lease_until = null,
    next_retry_at = null, safe_error_code = null, safe_error_message = null, updated_at = #{now}
where repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId}
  and (status in ('PENDING', 'READY', 'FAILED', 'STALE', 'CLEANUP_PENDING')
    or (status = 'RUNNING' and (lease_until is null or lease_until <= #{now})))

mapper.select:
select  from app_source_operations
where operation_id = (
    select operation.operation_id
    from app_source_operations operation
    join app_source_operation_steps step on step.operation_id = operation.operation_id
    where operation.repository_id = #{repositoryId}
      and operation.target_generation = #{generation}
      and operation.status in ('PENDING', 'RUNNING')
      and step.linux_server_id = #{linuxServerId}
      and step.scope = 'SERVER'
    order by operation.accepted_at desc, operation.operation_id desc
    limit 1
)

mapper.update:
update app_source_operation_steps step
set status = #{row.status}, safe_summary = #{row.safeSummary},
    started_at = #{row.startedAt}, completed_at = #{row.completedAt}, updated_at = #{row.updatedAt}
where step.step_id = #{row.stepId}
  and step.operation_id = #{row.operationId}
  and step.scope = 'SERVER'
  and step.linux_server_id = #{linuxServerId}
  and ((step.status = 'PENDING' and #{row.status} in ('RUNNING', 'FAILED', 'SKIPPED'))
    or (step.status = 'RUNNING' and #{row.status} in ('SUCCEEDED', 'FAILED', 'SKIPPED')))
  and exists (
    select 1
    from app_source_operations operation
    join app_source_replicas replica
      on replica.repository_id = operation.repository_id
     and replica.generation = operation.target_generation
     and replica.linux_server_id = #{linuxServerId}
    where operation.operation_id = #{row.operationId}
      and operation.repository_id = #{repositoryId}
      and operation.target_generation = #{generation}
      and operation.status in ('PENDING', 'RUNNING')
      and #{row.scope} = 'SERVER'
      and #{row.linuxServerId} = #{linuxServerId}
      and replica.status = 'RUNNING'
      and replica.lease_owner = #{expectedLeaseOwner}
      and replica.lease_until > #{now}
  )

mapper.insert:
insert into app_source_operation_steps()
select #{row.stepId}, #{row.operationId}, #{row.scope}, #{row.linuxServerId}, #{row.stepCode},
    #{row.sequence}, 'PENDING', #{row.safeSummary}, null, null, #{row.updatedAt}
where exists (
    select 1
    from app_source_operations operation
    join app_source_replicas replica
      on replica.repository_id = operation.repository_id
     and replica.generation = operation.target_generation
     and replica.linux_server_id = #{linuxServerId}
    where operation.operation_id = #{row.operationId}
      and operation.repository_id = #{repositoryId}
      and operation.target_generation = #{generation}
      and operation.status in ('PENDING', 'RUNNING')
      and #{row.scope} = 'SERVER'
      and #{row.linuxServerId} = #{linuxServerId}
      and replica.status = 'RUNNING'
      and replica.lease_owner = #{expectedLeaseOwner}
      and replica.lease_until > #{now}
  )
on conflict (step_id) do update set status = 'PENDING', safe_summary = excluded.safe_summary,
    started_at = null, completed_at = null, updated_at = excluded.updated_at

mapper.select:
select  from app_source_cleanup_tasks
where linux_server_id = #{linuxServerId} and delete_at <= #{now}
  and (status = 'PENDING'
    or (status = 'RETRY_WAIT' and (next_retry_at is null or next_retry_at <= #{now}))
    or (status = 'RUNNING' and lease_until <= #{now}))
order by delete_at, cleanup_task_id limit #{limit}

mapper.update:
update app_source_cleanup_tasks set status = 'RUNNING', lease_owner = #{leaseOwner}, lease_until = #{leaseUntil},
    attempt_count = attempt_count + 1, next_retry_at = null, updated_at = #{now}
where cleanup_task_id = #{cleanupTaskId} and delete_at <= #{now}
  and (status = 'PENDING'
    or (status = 'RETRY_WAIT' and (next_retry_at is null or next_retry_at <= #{now}))
    or (status = 'RUNNING' and lease_until <= #{now}))

update app_source_cleanup_tasks set status = 'RETRY_WAIT', lease_owner = null, lease_until = null,
    attempt_count = #{attemptCount}, next_retry_at = #{nextRetryAt}, safe_error_code = #{safeErrorCode},
    safe_error_message = #{safeErrorMessage}, updated_at = #{now}
where cleanup_task_id = #{cleanupTaskId} and status = 'RUNNING'
  and lease_owner = #{leaseOwner} and lease_until > #{now}

update app_source_cleanup_tasks set status = 'CLEANED', lease_owner = null, lease_until = null,
    next_retry_at = null, safe_error_code = null, safe_error_message = null, updated_at = #{now}
where cleanup_task_id = #{cleanupTaskId} and status = 'RUNNING'
  and lease_owner = #{leaseOwner} and lease_until > #{now}

update app_source_cleanup_tasks set status = 'SUPERSEDED', lease_owner = null, lease_until = null,
    next_retry_at = null, updated_at = #{now}
where cleanup_task_id = #{cleanupTaskId} and status in ('PENDING', 'RUNNING', 'RETRY_WAIT')

mapper.select:
select  from app_source_cleanup_tasks
where repository_id = #{repositoryId} and generation = #{generation} and linux_server_id = #{linuxServerId}
order by cleanup_task_id

mapper.update:
update app_source_cleanup_tasks
set delete_at = case when delete_at < #{now} then delete_at else #{now} end,
    next_retry_at = case when next_retry_at is null or next_retry_at > #{now} then #{now} else next_retry_at end,
    updated_at = #{now}
where repository_id = #{repositoryId} and generation = #{generation}
  and status in ('PENDING', 'RETRY_WAIT')
